import React from 'react';
import Section from '../components/Section';

const articles = [
    {
        title: 'Makueni Launches Export Training for Farmers',
        date: 'Sept 12, 2023',
        excerpt: 'The county government partners with local aggregators to train 500+ avocado and mango farmers on GlobalGAP and HACCP standards.',
        link: '#'
    },
    {
        title: 'New Mango Export Market Opens in Qatar',
        date: 'Sept 10, 2023',
        excerpt: 'FreshHarvest Ltd secures deal to supply Kenyan mangoes to Qatar. Export volumes expected to grow by 15% this season.',
        link: '#'
    },
];

const NewsAndInsightsPage = ({ onNavigate }) => (
    <div className="container mx-auto px-4 py-8">
        <Section title="News & Insights">
            <div className="space-y-6">
                {articles.map((article, index) => (
                    <div key={index} className="bg-white dark:bg-[#2C2C2C] p-6 rounded shadow">
                        <h3 className="text-xl font-bold text-gray-800 dark:text-white">{article.title}</h3>
                        <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">{article.date}</p>
                        <p className="text-gray-700 dark:text-gray-300">{article.excerpt}</p>
                        <a href={article.link} className="text-teal-700 hover:underline mt-2 inline-block">Read More</a>
                    </div>
                ))}
            </div>
        </Section>
    </div>
);

export default NewsAndInsightsPage;
